import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    if a == 0 or b == 0:
        return 0
    return abs(a * b) // gcd(a, b)

def calculate_x_k(k, n):
    if n == 0:
        return 1 # Convention, though k starts from 1 in context
    if n == 1:
        return k

    # Calculate LCM of k, k+1, ..., k+n-1
    result = k
    for i in range(1, n):
        result = lcm(result, k + i)
    return result

# Task specific parameters
n = 3
limit = 100

# Calculate initial values for comparison
# We check k from 1 up to limit - 1, since we compare x_k and x_{k+1}
# If k = limit - 1 = 99, we check x_100 vs x_99.

failed_k = None

print(f"Checking n={n} up to k={limit-1}...")

for k in range(1, limit):
    x_k = calculate_x_k(k, n)
    x_k_plus_1 = calculate_x_k(k + 1, n)

