import math
from functools import reduce

def lcm(a, b):
    return abs(a * b) // math.gcd(a, b)

def get_lcm_sequence(n, limit):
    x = []
    for k in range(1, limit + 1):
        nums = list(range(k, k + n))
        res = reduce(lcm, nums)
        x.append(res)
    return x

def check_weakly_increasing(n, limit):
    x = get_lcm_sequence(n, limit)
    # We want to check if x[i+1] > x[i] for all i > N
    # So we check if there are infinitely many i such that x[i+1] <= x[i]
    # For a fixed n, we can check if x[i+1] <= x[i] occurs for large i.
    # Let's check for i up to limit-1.
    # If x[i+1] <= x[i] happens for i close to limit, it's likely not weakly increasing.

    decreases_or_equal = []
    for i in range(len(x) - 1):
        if x[i+1] <= x[i]:
            decreases_or_equal.append(i)

    if not decreases_or_equal:
        return True, "Strictly increasing"
    else:
        # Check if the last few indices are in decreases_or_equal
        # This is a heuristic. If x[i+1] <= x[i] happens for very large i, it's not.
        last_idx = decreases_or_equal[-1]
        if last_idx > limit * 0.8:
            return False, f"Last decrease/equal at index {last_idx}"
        else:
            return True, f"Last decrease/equal at index {last_idx}"

# Let's test n from 1 to 10
results = {}
for n in range(1, 11):
    # We'll test a larger limit to be more confident
    # Let's try limit = 1000 and 2000
    res, msg = check_weakly_increasing(n, 1000)
    results[n] = (res, msg)
    print(f"n={n}: {results[n]}")

